export declare const inspectorStyles = "\n/* ---- \u5C5E\u6027\u680F\u5BB9\u5668\u4E0E\u63A7\u4EF6 ---- */\n.wf-inspector {\n  flex: none;\n  width: auto;\n  height: 100%;\n  max-height: 100%;\n  display: flex;\n  flex-direction: column;\n  background: var(--wf-layer);\n  overflow: hidden;\n  min-height: 0;\n}\n\n.wf-inspector__scroll {\n  flex: 1 1 0;\n  height: 0;\n  min-height: 0;\n  overflow: auto;\n  overscroll-behavior: contain;\n  padding: 15px;\n  display: flex;\n  flex-direction: column;\n  gap: 11px;\n  scrollbar-width: thin;\n}\n\n.wf-inspector__scroll>* {\n  flex-shrink: 0;\n}\n\n.wf-inspector.is-collapsed {\n  visibility: hidden;\n  pointer-events: none;\n  padding: 0;\n  width: 0 !important;\n}\n\n.wf-inspector h3 {\n  margin: 0;\n  font-size: 14px;\n  color: var(--wf-ink);\n}\n\n.wf-inspector label {\n  display: grid;\n  gap: 4px;\n  color: var(--wf-ink-2);\n  font-size: 12px;\n}\n\n.wf-inspector input,\n.wf-inspector select,\n.wf-inspector textarea {\n  width: 100%;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 7px;\n  background: var(--wf-layer-2);\n  color: var(--wf-ink);\n  padding: 6px 8px;\n  outline: 0;\n}\n\n.wf-inspector input:focus,\n.wf-inspector select:focus,\n.wf-inspector textarea:focus {\n  border-color: var(--wf-brand);\n}\n\n.wf-inspector textarea {\n  min-height: 92px;\n  resize: none;\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  font-size: 11px;\n  line-height: 1.55;\n}\n\n.wf-inspector__footer {\n  position: relative;\n  flex: none;\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  padding: 10px 14px;\n  border-top: 1px solid var(--wf-border);\n  background: var(--wf-layer);\n}\n\n.wf-inspector__footer .wf-btn {\n  font-size: 11px;\n  padding: 5px 11px;\n}\n\n/* ---- \u8D44\u4EA7\u7248\u672C\u4E0A\u62C9\u5217\u8868\uFF08\u5E95\u90E8\u300C\u56DE\u6EDA\u300D\u6309\u94AE\u5C55\u5F00\uFF09 ---- */\n.wf-asset-versions__backdrop {\n  position: fixed;\n  inset: 0;\n  z-index: 30;\n}\n\n.wf-asset-versions {\n  position: absolute;\n  z-index: 31;\n  left: 10px;\n  right: 10px;\n  bottom: 100%;\n  margin-bottom: 6px;\n  max-height: 240px;\n  overflow: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  padding: 9px 10px;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 9px;\n  background: var(--wf-layer-2);\n  box-shadow: 0 12px 30px color-mix(in srgb, var(--wf-ink) 12%, transparent);\n  scrollbar-width: thin;\n}\n\n.wf-asset-versions__head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n}\n\n.wf-asset-versions__title {\n  font-size: 11px;\n  font-weight: 650;\n  color: var(--wf-ink);\n}\n\n.wf-asset-versions__hint {\n  color: var(--wf-ink-2);\n  font-size: 11px;\n}\n\n.wf-asset-versions__list {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.wf-asset-versions__item {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  width: 100%;\n  text-align: left;\n  border: 1px solid var(--wf-border);\n  border-radius: 7px;\n  background: var(--wf-layer);\n  color: var(--wf-ink);\n  font-size: 11px;\n  padding: 5px 8px;\n  cursor: pointer;\n}\n\n.wf-asset-versions__item:hover {\n  border-color: var(--wf-brand);\n}\n\n.wf-asset-versions__item.is-active {\n  border-color: var(--wf-brand);\n}\n\n.wf-asset-versions__version {\n  flex: none;\n  font-weight: 650;\n  color: var(--wf-brand);\n}\n\n.wf-asset-versions__name {\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.wf-asset-versions__meta {\n  flex: none;\n  color: var(--wf-ink-2);\n}\n\n.wf-asset-versions__badge {\n  flex: none;\n  padding: 0 6px;\n  border-radius: 999px;\n  border: 1px solid var(--wf-brand);\n  color: var(--wf-brand);\n  font-size: 9px;\n}\n\n.wf-inspector .wf-empty {\n  color: var(--wf-ink-2);\n  font-size: 12px;\n}\n\n.wf-field {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n/* \u5B57\u6BB5\u4E0E\u8868\u5355\u884C\u5E03\u5C40\uFF08\u5C5E\u6027\u680F\u8868\u5355\u5171\u7528\uFF1B\u6B64\u524D\u6563\u843D\u5728\u5404\u8868\u5355\u7684\u5185\u8054 style\uFF09 */\n.wf-form-stack {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n/* \u53EA\u8BFB\u7EDF\u8BA1\u6E05\u5355\uFF08\u7ECF\u9A8C\u300C\u957F\u671F\u7EDF\u8BA1\u300D\u533A\uFF09\uFF1A\u6807\u7B7E + \u6570\u503C\u4E24\u5217\uFF0C\u65E0\u63A7\u4EF6\u5916\u89C2\u2014\u2014\n   \u4E0E\u53EF\u7F16\u8F91\u5B57\u6BB5\u5728\u89C6\u89C9\u4E0A\u533A\u5206\uFF08\u7F16\u8F91\u533A\u6CBF\u7528 .wf-field \u7684\u8F93\u5165\u63A7\u4EF6\u6837\u5F0F\uFF09\u3002 */\n.wf-stat-list {\n  display: grid;\n  gap: 4px;\n  margin: 0;\n}\n\n.wf-stat {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 8px;\n}\n\n.wf-stat__label {\n  color: var(--wf-ink-2);\n  font-size: 11px;\n}\n\n.wf-stat__value {\n  margin: 0;\n  color: var(--wf-ink);\n  font-size: 11px;\n  font-variant-numeric: tabular-nums;\n}\n\n.wf-form-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.wf-form-grid-1 {\n  display: grid;\n  gap: 8px;\n}\n\n.wf-form-grid-2 {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 8px;\n}\n\n.wf-form-grid-wide {\n  display: grid;\n  grid-template-columns: 2fr 1fr;\n  gap: 8px;\n}\n\n.wf-form-preline {\n  white-space: pre-line;\n}\n\n.wf-form-check {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  justify-content: flex-start;\n}\n\n/* ---- \u591A\u884C\u6587\u672C\u57DF\uFF1A\u53F3\u4E0B\u89D2\u5C55\u5F00\u6309\u94AE + \u753B\u5E03\u533A\u57DF\u6269\u5C55\u5C42 ---- */\n.wf-textarea-wrap {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n}\n\n/* \u7ED9\u53F3\u4E0B\u89D2\u6309\u94AE\u7559\u51FA\u6587\u5B57\u5B89\u5168\u533A\uFF0C\u907F\u514D\u6700\u540E\u4E00\u884C\u6587\u5B57\u88AB\u6309\u94AE\u906E\u4F4F */\n.wf-textarea-wrap>textarea {\n  padding-right: 30px;\n}\n\n.wf-textarea__expand {\n  position: absolute;\n  right: 5px;\n  bottom: 5px;\n  width: 22px;\n  height: 22px;\n  padding: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 6px;\n  background: var(--wf-layer-2);\n  color: var(--wf-ink-2);\n  font-size: 12px;\n  line-height: 1;\n  cursor: pointer;\n  transition: border-color .14s ease, color .14s ease;\n}\n\n.wf-textarea__expand:hover {\n  border-color: var(--wf-brand);\n  color: var(--wf-brand);\n}\n\n/* \u6269\u5C55\u5C42\u6302\u5728\u753B\u5E03\u5BB9\u5668\u5185\uFF1A\u5DE6\u8FB9\u754C\u968F\u5DE6\u680F/\u5E95\u680F\u5207\u6362\u81EA\u52A8\u53D8\u5316\uFF0C\u53F3\u8FB9\u754C\u6B62\u4E8E\u5C5E\u6027\u680F\uFF1B\n   \u9876\u90E8\u4ECE\u753B\u5E03\u63A7\u5236\u680F\uFF0852px\uFF09\u4E4B\u4E0B\u5F00\u59CB\uFF0C\u4E0D\u906E\u6321\u9876\u90E8\u63A7\u5236\u680F\u3002 */\n.wf-text-expand {\n  position: absolute;\n  z-index: 20;\n  left: 0;\n  right: 0;\n  top: 52px;\n  bottom: 0;\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  background: var(--wf-bg);\n  border-top: 1px solid var(--wf-border);\n}\n\n.wf-text-expand__head {\n  flex: none;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 12px;\n  border-bottom: 1px solid var(--wf-border);\n  background: var(--wf-layer);\n}\n\n.wf-text-expand__title {\n  flex: 1;\n  min-width: 0;\n  color: var(--wf-ink);\n  font-size: 12px;\n  font-weight: 650;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.wf-text-expand__collapse {\n  flex: none;\n  width: 26px;\n  height: 26px;\n  padding: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border: 1px solid var(--wf-border-strong);\n  border-radius: 7px;\n  background: var(--wf-layer-2);\n  color: var(--wf-ink-2);\n  font-size: 13px;\n  line-height: 1;\n  cursor: pointer;\n}\n\n.wf-text-expand__collapse:hover {\n  border-color: var(--wf-brand);\n  color: var(--wf-brand);\n}\n\n.wf-text-expand__input {\n  flex: 1;\n  min-height: 0;\n  width: 100%;\n  box-sizing: border-box;\n  resize: none;\n  border: 0;\n  border-radius: 0;\n  background: var(--wf-bg);\n  color: var(--wf-ink);\n  padding: 12px 14px;\n  outline: 0;\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  font-size: 12px;\n  line-height: 1.6;\n}\n\n/* \u590D\u9009\u6846\u9700\u8986\u76D6 .wf-inspector input{width:100%}\uFF08\u5426\u5219\u88AB\u6491\u6210\u5927\u65B9\u6846\u3001\u4E0D\u8D34\u8FB9\uFF09 */\n.wf-inspector .wf-form-check__box {\n  width: auto;\n  flex: 0 0 auto;\n  padding: 0;\n  margin: 0;\n  min-width: 0;\n  accent-color: var(--wf-brand);\n}\n\n/* ---- \u590D\u9009\u6E05\u5355 / \u63D0\u793A / \u9AD8\u7EA7\u6298\u53E0 / \u8DEF\u5F84\u5C55\u793A ---- */\n.wf-check-list__row {\n  justify-content: space-between;\n}\n\n.wf-btn--xs {\n  font-size: 9px;\n  padding: 2px 6px;\n}\n\n.wf-check-list {\n  max-height: 190px;\n  overflow: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  padding: 6px;\n  border: 1px solid var(--wf-border);\n  border-radius: 8px;\n  background: var(--wf-layer-2);\n  scrollbar-width: thin;\n}\n\n.wf-check-list label {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  color: var(--wf-ink);\n  font-size: 11px;\n}\n\n.wf-hint {\n  color: var(--wf-ink-2);\n  font-size: 11px;\n}\n\n.wf-advanced {\n  border: 1px solid var(--wf-border);\n  border-radius: 9px;\n  background: var(--wf-layer-2);\n  padding: 0 9px;\n  margin: 12px 0 0;\n}\n\n.wf-advanced summary {\n  cursor: pointer;\n  padding: 8px 0;\n  color: var(--wf-ink-2);\n  font-size: 11px;\n  font-weight: 650;\n}\n\n.wf-advanced__content {\n  display: grid;\n  gap: 9px;\n  padding: 0 0 10px;\n}\n\n.wf-pathbox {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  padding: 9px 10px;\n  border: 1px solid var(--wf-border);\n  border-radius: 9px;\n  background: var(--wf-layer-2);\n}\n\n.wf-pathbox__label {\n  font-size: 10px;\n  color: var(--wf-ink-2);\n}\n\n.wf-pathbox__value {\n  font: 10px/1.45 ui-monospace, SFMono-Regular, Menlo, monospace;\n  color: var(--wf-ink);\n  word-break: break-all;\n}\n\n/* ---- \u56FE\u6807\u6309\u94AE\u4E0E\u7AD6\u5411\u5206\u9694\u6761 ---- */\n.wf-iconbtn {\n  width: 32px;\n  height: 32px;\n  padding: 0;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 16px;\n}\n\n.wf-splitter {\n  position: relative;\n  z-index: 12;\n  flex: none;\n  min-width: 9px;\n  width: 9px;\n  cursor: col-resize;\n  touch-action: none;\n  background: var(--wf-layer);\n  outline: 0;\n}\n\n.wf-splitter::before {\n  content: \"\";\n  position: absolute;\n  inset: 0 3px;\n  background: var(--wf-border);\n}\n\n.wf-splitter:hover::before,\n.wf-splitter:focus-visible::before,\n.wf-splitter.is-dragging::before {\n  inset: 0 2px;\n  background: var(--wf-brand);\n}\n";
